    `btn-${variant}`,
    `btn--state-${state}`,
    `btn--type-${resolvedVisualType}`,
    isHover && 'btn--show-hover',
    isPressed && 'btn--selected',
    isFocus && 'btn--state-focus',
    fullWidth && 'btn--full-width',
    isDisabled && 'btn--disabled',
    className
