      type={htmlButtonType}
      className={combinedClasses}
      disabled={isDisabled}
      aria-busy={loading || undefined}
      aria-pressed={isPressed || undefined}
    >
      {isIconOnly ? (
        renderIcon(leftIcon || rightIcon || true, 'left')
